"""Full-sequence AdamW transfer ladder and measured rate brackets."""

import math
from itertools import pairwise

from .formatting import bpb, bpb_delta, one


def figure(points: list[dict]) -> str:
    """Shared BPB curves and a within-diffusion difference, with one keyed legend."""
    lines = [
        "% Generated by scaling_figure.py; do not edit by hand.",
        r"\begingroup\setlength{\unitlength}{1mm}",
        r"\definecolor{scaleAR}{RGB}{38,93,132}",
        r"\definecolor{scaleScratch}{RGB}{191,102,34}",
        r"\definecolor{scaleConversion}{RGB}{0,118,104}",
        r"\begin{picture}(160,70)",
    ]

    def text(x: float, y: float, value: str, anchor: str = "c") -> None:
        lines.append(f"\\put({x:.3f},{y:.3f})" + r"{\makebox(0,0)[" + anchor + r"]{\scriptsize " + value + "}}")

    def line(x: float, y: float, xx: float, yy: float, color: str, thick: float = 0.3, dashed: bool = False) -> None:
        if dashed:
            length = math.hypot(xx - x, yy - y)
            for start in range(math.ceil(length / 2.4)):
                a, b = start * 2.4 / length, min((start * 2.4 + 1.5) / length, 1.0)
                # Tiny terminal fragments overflow TeX's automatic Bezier sampling.
                if (b - a) * length >= 0.3:
                    line(x + a * (xx - x), y + a * (yy - y), x + b * (xx - x), y + b * (yy - y), color, thick)
            return
        lines.append(
            f"{{\\color{{{color}}}\\linethickness{{{thick}pt}}\\qbezier({x:.3f},{y:.3f})({(x + xx) / 2:.3f},{(y + yy) / 2:.3f})({xx:.3f},{yy:.3f})}}"
        )

    def marker(x: float, y: float, family: str, color: str) -> None:
        # Repeat the plot glyphs in the legend; color alone need not identify a curve.
        if family == "scratch":
            lines.append(f"\\put({x - 0.7:.3f},{y - 0.7:.3f}){{\\color{{{color}}}\\rule{{1.4mm}}{{1.4mm}}}}")
        else:
            lines.append(f"\\put({x:.3f},{y:.3f}){{\\color{{white}}\\circle*{{1.8}}}}")
            if family == "ar":
                lines.append(f"\\put({x:.3f},{y:.3f}){{\\color{{{color}}}\\linethickness{{.7pt}}\\circle{{1.7}}}}")
            else:
                vertices = [(x, y + 0.95), (x + 0.95, y), (x, y - 0.95), (x - 0.95, y), (x, y + 0.95)]
                for (a, b), (c, d) in pairwise(vertices):
                    line(a, b, c, d, color, 0.8)

    by = {(p["depth"], p["family"]): p for p in points}
    depths = (4, 8, 10, 12, 16, 20)
    styles = {"ar": "scaleAR", "scratch": "scaleScratch", "conversion": "scaleConversion", "delta": "scaleConversion"}
    panels = [
        (
            11,
            84,
            "(a) Prediction scaling",
            0.80,
            1.60,
            [0.8, 1.0, 1.2, 1.4, 1.6],
            r"Bits per byte $\downarrow$",
            (20, 50, 100, 200, 500),
            ("ar", "scratch", "conversion"),
        ),
        (
            117,
            41,
            "(b) Conversion minus scratch",
            -0.075,
            0.008,
            [-0.06, -0.04, -0.02, 0.0],
            r"$\Delta$ NELBO BPB $\downarrow$",
            (20, 100, 500),
            ("delta",),
        ),
    ]
    for left, width, title, lo, hi, ticks, ylabel, xticks, series in panels:
        bottom, height = 18, 38
        center = left + width / 2

        def xx(n, left=left, width=width):
            return left + math.log(n / 17) / math.log(550 / 17) * width

        def yy(n, bottom=bottom, lo=lo, hi=hi, height=height):
            return bottom + (n - lo) / (hi - lo) * height

        text(center, 66, r"\textbf{" + title + "}")
        text(center, 61, ylabel)
        for tick in ticks:
            line(left, yy(tick), left + width, yy(tick), "gray!25")
            text(left - 1.5, yy(tick), f"{tick:.2f}" if lo < 0 else f"{tick:.1f}", "r")
        for tick in xticks:
            line(xx(tick), bottom, xx(tick), bottom + height, "gray!15")
            text(xx(tick), bottom - 3, str(tick))
        line(left, bottom, left, bottom + height, "black")
        line(left, bottom, left + width, bottom, "black")
        if lo < 0:
            line(left, yy(0), left + width, yy(0), "gray!65", 0.5)
        text(center, 10, "Parameters (M; log scale)")
        for family in series:
            color = styles[family]
            coords = []
            for depth in depths:
                base = by[(depth, "scratch" if family == "delta" else family)]
                value = by[(depth, "conversion")]["bpb"] - base["bpb"] if family == "delta" else base["bpb"]
                assert lo <= value <= hi
                coords.append((xx(base["total_parameters"] / 1e6), yy(value)))
            for (x, y), (nx, ny) in pairwise(coords):
                line(x, y, nx, ny, color, 1.1, dashed=family == "ar")
            for x, y in coords:
                marker(x, y, family, color)
    for left, family, label in [
        (1, "ar", "AR20 (causal BPB)"),
        (49, "scratch", "MDLM40 (NELBO)"),
        (101, "conversion", "AR20 + MDLM20 (NELBO)"),
    ]:
        color = styles[family]
        line(left, 2, left + 8, 2, color, 1.1, dashed=family == "ar")
        marker(left + 4, 2, family, color)
        text(left + 11, 2, label, "l")
    lines.append(r"\end{picture}\endgroup")
    # Whitespace between picture commands otherwise shifts their local origin.
    return "%\n".join(lines) + "%\n"


def transfer_table(brackets: dict, transferred_rates: dict, points: list[dict]) -> str:
    rows = []
    for depth in (10, 12, 16, 20):
        size = f"{one(points, depth=depth, family='scratch')['total_parameters'] / 1e6:.0f}M"
        for family, label in (("scratch", "Scratch"), ("conversion", "AR-initialized")):
            if depth in (10, 12):
                for variant in ("fixed", "coupled"):
                    bracket = brackets[f"{family}_d{depth}_{variant}"]
                    rate = bracket[1]["lr"]
                    losses = [bpb(r["bpb"]) for r in bracket]
                    rows.append([size, label, variant, f"{1000 * rate:.5f}", *losses])
            else:
                point = one(points, depth=depth, family=family)
                rate = transferred_rates[(depth, family)]
                rows.append([size, label, "coupled", f"{1000 * rate:.5f}", "---", bpb(point["bpb"]), "---"])
    body = "\n".join(" & ".join(row) + r" \\" for row in rows)
    return (
        r"""% Generated by scaling_figure.py.
\begin{table*}[t]
\centering\small
\begin{tabular}{@{}rllrrrr@{}}\toprule
 & & & Predicted root LR & \multicolumn{3}{c}{Diffusion NELBO (BPB)} \\
\cmidrule(l){5-7}
Size & Recipe & AdamW & ($\times10^{-3}$) & Half rate & Predicted rate & Double rate \\
\midrule
"""
        + body
        + "\n"
        + r"""\bottomrule\end{tabular}
\caption{Learning-rate transfer for full-sequence diffusion. Each measured cell is one trained endpoint scored with four corruption plans. At 91M and 135M parameters the predicted rate gives the lowest loss in every row. Dashes mark rates left untested at the two largest sizes.}
\label{tab:full-sequence-lr-transfer}
\end{table*}
"""
    )


def table(points: list[dict]) -> str:
    rows = []
    for depth in (4, 8, 10, 12, 16, 20):
        a, s, c = [one(points, depth=depth, family=f) for f in ("ar", "scratch", "conversion")]
        rows.append(
            f"D{depth} & {a['total_parameters'] / 1e6:.2f} & {bpb(a['bpb'])} & {bpb(s['bpb'])} & {bpb(c['bpb'])} & {bpb_delta(c['bpb'] - s['bpb'])} "
            + r"\\"
        )
    return (
        "% Generated by scaling_figure.py.\n"
        + r"""\begin{table*}[t]
\centering\small
\begin{tabular}{@{}lrrrrr@{}}\toprule
Depth & Total params (M) & AR20 BPB & Scratch40 NELBO & AR20+MDLM20 NELBO & Conversion $-$ scratch \\
\midrule
"""
        + "\n".join(rows)
        + "\n"
        + r"""\bottomrule\end{tabular}
\caption{\textbf{Retained full-sequence transfer endpoints.} Exact numerical companion to Figure~\ref{fig:scaling}. Width is $64D$. AR rows are the actual conversion parents (including the earlier pinned 59M parent), not a latest-best AR envelope. Its TPP20 causal likelihood is not the same estimator or budget as the diffusion TPP40 bound. Within-size diffusion budgets include the full AR parent; smaller models have more search than the transferred settings at 268M and 477M. One training seed per endpoint; four corruption-plan means for diffusion, not four training repeats. Both historical diffusion arms use AdamW, with ordinary parameterization at the four-layer base shape and CompleteP at the five larger sizes.}
\label{tab:scaling}
\end{table*}
"""
    )


def render(scaling):
    points = scaling["points"]
    rates = {
        (int(depth), family): rate
        for depth, row in scaling["transferred_rates"].items()
        for family, rate in row.items()
    }
    return {
        "figures/scaling.tex": figure(points),
        "tables/scaling.tex": table(points),
        "tables/full-sequence-lr-transfer.tex": transfer_table(scaling["brackets"], rates, points),
    }
